import {architecture,useCases} from './content.js';
const $=id=>document.getElementById(id);
let architectureView='bda', selectedStage=0;
function selectStage(index){selectedStage=index;const stage=architecture[architectureView].stages[index];$('component-number').textContent=String(index+1).padStart(2,'0');$('component-title').textContent=stage[0];$('component-description').textContent=stage[2];$('component-connection').textContent=stage[3];document.querySelectorAll('.architecture-node').forEach((button,i)=>button.setAttribute('aria-pressed',String(i===index)));}
function renderArchitecture(view){architectureView=view;document.querySelectorAll('[data-architecture]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.architecture===view)));$('architecture-nodes').replaceChildren(...architecture[view].stages.map((stage,index)=>{const button=document.createElement('button');button.className='architecture-node';button.setAttribute('aria-controls','component-detail');button.setAttribute('aria-label',`${index+1}. ${stage[0]}: ${stage[1]}`);const number=document.createElement('span');number.textContent=String(index+1).padStart(2,'0');const title=document.createElement('strong');title.textContent=stage[0];const tool=document.createElement('small');tool.textContent=stage[1];button.append(number,title,tool);button.addEventListener('click',()=>selectStage(index));return button;}));selectStage(0);}
document.querySelectorAll('[data-architecture]').forEach(b=>b.addEventListener('click',()=>renderArchitecture(b.dataset.architecture)));renderArchitecture('bda');
function showUseCase(key){const scenario=useCases[key];document.querySelectorAll('[data-case]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.case===key)));$('case-setting').textContent=scenario.setting;$('case-title').textContent=scenario.title;$('case-situation').textContent=scenario.situation;$('case-challenge').textContent=scenario.challenge;$('case-help').textContent=scenario.help;$('case-lesson').textContent=scenario.lesson;$('case-process').replaceChildren(...scenario.steps.map((step,index)=>{const item=document.createElement('span');const number=document.createElement('small');number.textContent=String(index+1).padStart(2,'0');const label=document.createElement('strong');label.textContent=step;item.append(number,label);return item;}));}
document.querySelectorAll('[data-case]').forEach(button=>button.addEventListener('click',()=>showUseCase(button.dataset.case)));showUseCase('campus');
function updateSimulation(){const demand=Number($('demand').value),renewable=Number($('renewable').value),shift=Number($('shift').value),net=demand*(1-shift/100),used=Math.min(renewable,net),conventional=Math.max(net-renewable,0),surplus=Math.max(renewable-net,0),deferred=demand-net;const fmt=value=>Number(value.toFixed(1)).toLocaleString('en-IN');$('demand-value').textContent=demand+' MW';$('renewable-value').textContent=renewable+' MW';$('shift-value').textContent=shift+'%';$('conventional').textContent=fmt(conventional);$('net-demand').textContent=fmt(net)+' MW';$('renewable-used').textContent=fmt(used)+' MW';$('surplus').textContent=fmt(surplus)+' MW';$('deferred').textContent=fmt(deferred)+' MWh';$('renewable-bar').style.width=(used/net*100)+'%';$('conventional-bar').style.width=(conventional/net*100)+'%';$('simulation-explanation').textContent=`Renewables cover ${Math.round(used/net*100)}% of demand in this hour.`;}
['demand','renewable','shift'].forEach(id=>$(id).addEventListener('input',updateSimulation));$('reset-simulation').addEventListener('click',()=>{$('demand').value=100;$('renewable').value=60;$('shift').value=10;updateSimulation();});updateSimulation();
const toggle=document.querySelector('.menu-toggle'),links=$('nav-links');function closeMenu(){toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Open navigation');links.classList.remove('open');}
toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')==='true';toggle.setAttribute('aria-expanded',String(!open));toggle.setAttribute('aria-label',open?'Open navigation':'Close navigation');links.classList.toggle('open',!open);});links.querySelectorAll('a').forEach(link=>link.addEventListener('click',closeMenu));document.addEventListener('keydown',event=>{if(event.key==='Escape'&&toggle.getAttribute('aria-expanded')==='true'){closeMenu();toggle.focus();}});window.addEventListener('resize',()=>{if(window.innerWidth>700)closeMenu();});
const reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)');if('IntersectionObserver' in window&&!reduceMotion.matches){document.body.classList.add('motion-ready');const revealObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');revealObserver.unobserve(entry.target);}});},{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>revealObserver.observe(el));reduceMotion.addEventListener('change',()=>{if(reduceMotion.matches){document.body.classList.remove('motion-ready');revealObserver.disconnect();}});}
if('IntersectionObserver' in window){const navigationObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){links.querySelectorAll('a').forEach(a=>{if(a.hash==='#'+entry.target.id)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});}});},{rootMargin:'-20% 0px -55% 0px',threshold:0});['problem','architecture','outcomes','use-cases'].forEach(id=>navigationObserver.observe($(id)));}
